UPDATE public.contacts SET send_status = 'skipped', error = 'Your current company' WHERE send_status IN ('pending','approved') AND (company ILIKE '%dassault%' OR email ILIKE '%@3ds.com' OR email ILIKE '%solidworks%');
UPDATE public.jobs SET status = 'failed', error = 'Your current company — skipped' WHERE status <> 'failed' AND (company ILIKE '%dassault%' OR company_domain ILIKE '%3ds.com%');